+      },
+      {
+        id: 'q2',
+        prompt: 'Which are commonly used in backend development?',
+        choices: [
+          { id: 'q2-python', label: 'Python', correct: true, note: 'Popular for APIs and server code.' },
+          { id: 'q2-ruby', label: 'Ruby', correct: true, note: 'Often used with web frameworks.' },
+          { id: 'q2-sql', label: 'SQL', correct: true, note: 'Used to query and manage data.' },
+          { id: 'q2-figma', label: 'Figma', correct: false, note: 'A design tool, not a language.' }
+        ]
+      },
+      {
+        id: 'q3',
+        prompt: 'Which are statically typed languages?',
+        choices: [
+          { id: 'q3-typescript', label: 'TypeScript', correct: true, note: 'Adds static types to JavaScript.' },
+          { id: 'q3-java', label: 'Java', correct: true, note: 'Strongly typed and compiled.' },
+          { id: 'q3-csharp', label: 'C#', correct: true, note: 'Statically typed and widely used.' },
+          { id: 'q3-lua', label: 'Lua', correct: false, note: 'Generally dynamically typed.' }
+        ]
+      }
+    ];
+
+    const h = (tag, attrs = {}, ...children) => {
+      const node = document.createElement(tag);
+      Object.entries(attrs).forEach(([key, value]) => {
+        if (value === null || value === undefined || value === false) return;
+        if (key === 'className') {
+          node.className = value;
+          return;
+        }
+        if (key === 'textContent') {
+          node.textContent = value;
+          return;
+        }
+        if (key.startsWith('aria-') || key === 'role' || key === 'type' || key === 'id' || key === 'name' || key === 'for' || key === 'value' || key === 'required' || key === 'tabindex' || key === 'hidden') {
+          node.setAttribute(key, value === true ? '' : value);
+          return;
+        }
+        node[key] = value;
+      });
+      children.flat().forEach((child) => {
+        if (child === null || child === undefined || child === false) return;
+        node.append(child.nodeType ? child : document.createTextNode(String(child)));
+      });
+      return node;
+    };
+
+    function Question({ id, prompt, helpText, choices }, index) {
+      const fieldset = h('fieldset', {
+        'aria-describedby': helpText ? `${id}-help` : null
+      });
+      const legend = h('legend', {}, prompt);
+      fieldset.appendChild(legend);
+
+      if (helpText) {
+        fieldset.appendChild(
+          h('p', { id: `${id}-help`, className: 'help-text' }, helpText)
+        );
+      }
+
+      const choiceList = h('div', { className: 'choice-list' });
+      choices.forEach((choice, choiceIndex) => {
+        const inputId = choice.id;
+        const input = h('input', {
+          id: inputId,
+          type: 'checkbox',
+          name: id,
+          value: choice.label
+        });
+
+        const label = h(
+          'label',
+          { className: 'choice', for: inputId },
+          input,
+          h(
+            'span',
+            { className: 'choice-text' },
+            h('span', { className: 'choice-title' }, choice.label),
+            h('span', { className: 'choice-subtitle' }, choice.note)
+          )
+        );
+
+        choiceList.appendChild(label);
+      });
+
+      fieldset.appendChild(choiceList);
+
+      return h('div', { className: 'form-field' }, fieldset);
+    }
+
+    function App() {
+      const questionsHost = document.getElementById('quiz-questions');
+      quizData.forEach((question, index) => {
+        questionsHost.appendChild(Question(question, index));
+      });
+
+      const form = document.getElementById('quiz-form');
+      const result = document.getElementById('quiz-result');
+
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+
+        let score = 0;
+        const total = quizData.length;
+        const details = [];
+
+        quizData.forEach((question) => {
+          const selected = [...form.querySelectorAll(`input[name="${question.id}"]:checked`)].map((input) => input.value);
+          const correct = question.choices.filter((choice) => choice.correct).map((choice) => choice.label);
+
+          const selectedSorted = [...selected].sort();
+          const correctSorted = [...correct].sort();
+          const isPerfectMatch = selectedSorted.length === correctSorted.length &&
+            selectedSorted.every((item, index) => item === correctSorted[index]);
+
+          if (isPerfectMatch) {
+            score += 1;
+          }
+
+          details.push(`${question.prompt} ${isPerfectMatch ? '✓' : '✕'}`);
+        });
+
+        result.dataset.state = score === total ? 'success' : 'neutral';
+        result.innerHTML = `
+          <strong>You scored ${score} out of ${total}.</strong>
+          <span>${details.join(' · ')}</span>
+        `;
+        result.focus();
+      });
+    }
+
+    App();
+  </script>
+</body>
+</html>
*** End Patch
